def _curl_session(impersonate="chrome110"):
    """Return curl_cffi session or requests.Session fallback. Never returns None."""
    if curl_requests is not None:
        try:
            try:
                s = curl_requests.Session(impersonate=impersonate)
            except TypeError:
                s = curl_requests.Session()
                try:
                    s.impersonate = impersonate
                except Exception:
                    pass
            return s
        except Exception:
            pass
    return requests.Session()


def _safe_net_exc():
    """Exception tuple safe when curl_cffi/httpx missing."""
    ex = [
        requests.exceptions.ProxyError,
        requests.exceptions.Timeout,
        requests.exceptions.ConnectionError,
        requests.exceptions.RequestException,
        ConnectionResetError,
        BrokenPipeError,
        OSError,
    ]
    if curl_requests is not None:
        try:
            ex.extend([
                curl_requests.errors.ProxyError,
                curl_requests.errors.Timeout,
                curl_requests.errors.ConnectionError,
            ])
        except Exception:
            pass
    if httpx is not None:
        try:
            ex.extend([httpx.ConnectError, httpx.TimeoutException, httpx.NetworkError])
        except Exception:
            pass
    return tuple(ex)


