def safe_strftime(dt, fmt="%Y-%m-%d %H:%M:%S", default="N/A"):
    """Never call .strftime on None."""
    if dt is None:
        return default
    try:
        if isinstance(dt, str):
            s = dt.strip()
            if not s or s.upper() in ("NONE", "N/A", "NULL", "-"):
                return default
            try:
                dt = datetime.fromisoformat(s.replace("Z", "+00:00"))
            except Exception:
                return s
        return dt.strftime(fmt)
    except Exception:
        return default



