def _mk_btn(text, *, callback_data=None, url=None, emoji=None, style=None, wide=True):
    """Premium-only button icons. No normal unicode emoji on button text."""
    raw = str(text or "").strip()
    # strip ALL emoji/symbols from visible label
    clean = re.sub(
        r"[\U0001F300-\U0001FAFF\u2600-\u27BF\u2300-\u23FF\u2000-\u206F\uFE0F\u20E3"
        r"⬅➡⬆⬇✔❌✅⭐🔥🎬🔒🛠🎵🏆✨🔙«»⏹🚀💎⚙⭐️✅❌⬅️➡️«»·•]+",
        "",
        raw,
    )
    clean = re.sub(r"\s+", " ", clean).strip() or "·"
    if wide and url is None:
        clean = wide_btn_text(clean, 28)

    cb = str(callback_data or "").lower()
    # Back / checker back -> premium ✅ only
    if "back" in clean.lower() or "back" in cb or cb in ("menu_checkers", "admin_back", "admin_panel"):
        if "back" in clean.lower() or "back" in cb:
            emoji = "✅"

    if not emoji:
        tl = (clean + " " + cb).lower()
        auto = [
            ("stop", "🛑"), ("admin", "⚙️"), ("premium", "⭐️"), ("redeem", "🎁"),
            ("proxy", "🌐"), ("check", "🔥"), ("stat", "📊"), ("broadcast", "📬"),
            ("welcome", "📄"), ("media", "📁"), ("force", "🔗"), ("remove", "❌"),
            ("join", "🔗"), ("account", "👤"), ("multi", "🔀"), ("vpn", "🔒"),
            ("stream", "🎬"), ("tool", "🔧"), ("music", "🎵"), ("sport", "🎯"),
            ("other", "💠"), ("home", "📂"), ("start", "▶️"), ("hit", "💯"),
            ("free", "🆓"), ("bad", "🚫"), ("error", "⚠️"), ("gen", "✨"),
            ("code", "🔑"), ("list", "📋"), ("add", "➕"), ("delete", "🗑"),
            ("set", "⚙️"), ("view", "👀"), ("download", "⬇️"), ("upload", "📥"),
            ("search", "🔎"), ("save", "💾"), ("live", "🟢"), ("dead", "🔴"),
            ("recheck", "🔄"), ("panel", "🎛"), ("help", "❓"), ("skip", "⏩"),
            ("thread", "⚡"), ("cancel", "❌"), ("open", "📂"), ("mass", "🔥"),
            ("single", "👤"), ("category", "📂"), ("checker", "🔥"),
        ]
        for key, em in auto:
            if key in tl:
                emoji = em
                break
    if not emoji:
        pool = ["🔥", "💎", "⭐️", "🎯", "🎬", "🔒", "🎵", "🔧", "🌐", "🎮",
                "💜", "💙", "✨", "🔑", "📌", "🔔", "💰", "🧠", "🚀", "📡"]
        emoji = pool[abs(hash(clean + cb)) % len(pool)]

    if emoji not in SPECIAL_EMOJI_IDS:
        emoji = "✅"

    kwargs = {}
    if callback_data is not None:
        kwargs["callback_data"] = str(callback_data)
    if url is not None:
        kwargs["url"] = str(url)
    try:
        btn = types.InlineKeyboardButton(clean, **kwargs)
    except TypeError:
        btn = types.InlineKeyboardButton(text=clean, **kwargs)
    try:
        btn.style = style
    except Exception:
        pass
    try:
        btn.icon_custom_emoji_id = str(SPECIAL_EMOJI_IDS[emoji])
    except Exception:
        pass
    return btn

def btn(text, data, *, emoji=None, style=BTN_PRIMARY, wide=True):
    return _mk_btn(text, callback_data=data, emoji=emoji, style=style, wide=wide)

def btn_url(text, url, *, emoji=None, style=BTN_PRIMARY, wide=True):
    return _mk_btn(text, url=url, emoji=emoji, style=style, wide=wide)

def ikb(text, callback_data=None, url=None, style=None, wide=True, emoji=None):
    """Inline button with optional color style + premium emoji icon."""
    return _mk_btn(text, callback_data=callback_data, url=url, emoji=emoji, style=style, wide=wide)


# user_id -> {"stop": bool} for /stop during mass check
RUNNING_JOBS = {}
RUNNING_JOBS_LOCK = threading.Lock()
# free: 1 concurrent check; premium: 3 concurrent checks
def max_concurrent_checks(user_id):
    try:
        return 3 if is_premium(user_id) else 1
    except Exception:
        return 1

def count_user_jobs(user_id):
    with RUNNING_JOBS_LOCK:
        # support multi-job keys: uid or "uid:1"
        uid = int(user_id)
        n = 0
        for k, v in list(RUNNING_JOBS.items()):
            try:
                if int(str(k).split(":")[0]) == uid and v is not None:
                    n += 1
            except Exception:
                pass
        return n

def register_job(user_id):
    with RUNNING_JOBS_LOCK:
        uid = int(user_id)
        # find free slot
        for i in range(0, 10):
            key = uid if i == 0 and uid not in RUNNING_JOBS else f"{uid}:{i}"
            if key not in RUNNING_JOBS:
                RUNNING_JOBS[key] = {"stop": False, "uid": uid}
                return key
        # fallback overwrite primary
        RUNNING_JOBS[uid] = {"stop": False, "uid": uid}
        return uid

def set_job_stop(user_id):
    with RUNNING_JOBS_LOCK:
        uid = int(user_id)
        for k, v in list(RUNNING_JOBS.items()):
            try:
                if int(str(k).split(":")[0]) == uid and isinstance(v, dict):
                    v["stop"] = True
                    ev = v.get("event")
                    if ev is not None:
                        try:
                            ev.set()
                        except Exception:
                            pass
            except Exception:
                pass

def clear_job(job_key):
    with RUNNING_JOBS_LOCK:
        RUNNING_JOBS.pop(job_key, None)




# ==================== CUSTOM EMOJI MAPPING (Premium tg-emoji + fallbacks) ====================
# IDs from @fStikBot / @TgEmojis pack. Old keys preserved; new aliases added.
# Use E(key) or e_pair(start_key, end_key, text) so every line has different start/end emoji.
def send_rich_message(chat_id, text_blocks, buttons=None, parse_mode="HTML"):
    """Python port of sendRichMessage (rich_message blocks + styled buttons).
    Falls back to normal sendMessage + InlineKeyboard if API unsupported.
    """
    try:
        blocks = []
        if isinstance(text_blocks, str):
            blocks.append({"type": "paragraph", "text": text_blocks})
        elif isinstance(text_blocks, list):
            for t in text_blocks:
                if isinstance(t, dict):
                    blocks.append(t)
                else:
                    blocks.append({"type": "paragraph", "text": str(t)})
        if buttons:
            # buttons: list of rows of dicts {text, callback_data|url, style, disabled}
            all_btns = []
            for row in buttons:
                for b in (row if isinstance(row, (list, tuple)) else [row]):
                    item = {"text": str(b.get("text", "·"))}
                    if b.get("url"):
                        item["url"] = b["url"]
                    if b.get("callback_data"):
                        item["callback_data"] = str(b["callback_data"])
                    if b.get("style"):
                        item["style"] = b["style"]
                    if b.get("disabled"):
                        item["disabled"] = {}
                    all_btns.append(item)
            if all_btns:
                blocks.append({"type": "buttons", "align": "center", "buttons": all_btns})
        import requests as _rq
        api = f"https://api.telegram.org/bot{BOT_TOKEN}/sendRichMessage"
        payload = {"chat_id": chat_id, "rich_message": {"blocks": blocks}}
        r = _rq.post(api, json=payload, timeout=20)
        if r.status_code == 200:
            j = r.json()
            if j.get("ok"):
                return j.get("result")
    except Exception:
        pass
    # fallback classic
    markup = None
    if buttons:
        markup = types.InlineKeyboardMarkup()
        for row in buttons:
            row = row if isinstance(row, (list, tuple)) else [row]
            markup.row(*[
                ikb(
                    b.get("text", "·"),
                    callback_data=b.get("callback_data"),
                    url=b.get("url"),
                    style=b.get("style"),
                    emoji=b.get("emoji"),
                    wide=False,
                )
                for b in row
            ])
    body = text_blocks if isinstance(text_blocks, str) else "\n".join(
        (t if isinstance(t, str) else t.get("text", "")) for t in (text_blocks or [])
    )
    return bot.send_message(chat_id, body, parse_mode=parse_mode, reply_markup=markup)


