# Ordered pool for rotating start/end emojis on every line
_EMOJI_POOL = [
    "diamond", "success", "spark", "fireheart", "crown", "star", "gem", "rocket",
    "fire", "bolt", "glow", "party", "trophy", "thumb", "ok1", "tick", "boom",
    "gift1", "heart", "top", "pin", "cash", "megaphone", "starface", "cool",
    "glow2", "fire2", "hundred", "india", "world", "card", "bell", "robot",
    "angel", "devil", "wink", "laugh", "rofl", "champagne", "teddy", "moai",
]


def E(key, default="💎"):
    """Premium custom emoji HTML. Uses EMOJIS map then SPECIAL_EMOJI_IDS by glyph."""
    try:
        val = None
        if isinstance(EMOJIS, dict):
            val = EMOJIS.get(key) or EMOJIS.get(str(key).lower())
        if not val:
            val = key if key in SPECIAL_EMOJI_IDS else default
        if isinstance(val, str) and "tg-emoji" in val:
            return val
        glyph = val if isinstance(val, str) else default
        eid = SPECIAL_EMOJI_IDS.get(glyph) or SPECIAL_EMOJI_IDS.get(default)
        if eid:
            return '<tg-emoji emoji-id="%s">%s</tg-emoji>' % (eid, glyph)
        return glyph or default
    except Exception:
        return default


def plain_e(key, default="•"):
    """Unicode glyph from premium EMOJIS map (for progress when HTML fails / buttons)."""
    v = EMOJIS.get(key) or default
    if isinstance(v, str) and "tg-emoji" in v:
        m = re.search(r">([^<]+)<", v)
        return m.group(1) if m else default
    return v if isinstance(v, str) else default



def checker_icon(checker_id_or_type, default_key="poly_aio"):
    """Premium pack icon for a checker (title line)."""
    raw = str(checker_id_or_type or "").lower().strip()
