    lines += ["", f"{E('rijif_crown', '👑')} <b>Made By</b> ➜ {CONTACT_ADMIN}"]
    filtered = []
    for ln in lines:
        if not ln:
            filtered.append(ln); continue
        low = ln.lower()
        if ("➜ -" in low or "➜ n/a" in low) and "account" not in low and "made by" not in low:
            continue
        filtered.append(ln)
    return "\n".join(filtered)



