    def _run(self, email: str, password: str, proxy: Optional[str]) -> Dict:
        import asyncio
        import importlib.util
        path = _find_ext_module("exxen_checker.py")
        if not path:
            return {"status": "error", "message": "exxen module missing — redeploy zip with checkers_ext"}
        spec = importlib.util.spec_from_file_location("exxen_ext", path)
        mod = importlib.util.module_from_spec(spec)
        try:
            spec.loader.exec_module(mod)
        except Exception as e:
            return {"status": "error", "message": f"exxen load: {e}"[:100]}
        try:
            mod.AUTHOR_TAG = "TG: @samviir"
            mod.DEBUG = False
        except Exception:
            pass
        if proxy and hasattr(mod, "Eyelifter_format_proxy"):
            try:
                proxy = mod.Eyelifter_format_proxy(proxy)
            except Exception:
                pass
        elif proxy and not str(proxy).startswith(("http://", "https://", "socks")):
            proxy = f"http://{proxy}"

