def _write_all_embedded_ext():
    try:
        here = os.path.dirname(os.path.abspath(__file__))
    except Exception:
        here = os.getcwd()
    dest_dir = os.path.join(here, "checkers_ext")
    try:
        os.makedirs(dest_dir, exist_ok=True)
    except Exception:
        pass
    import base64 as _b64
    for name, chunks in _EMBEDDED_EXT_MODULES.items():
        try:
            raw = _b64.b64decode("".join(chunks))
        except Exception:
            continue
        for path in (os.path.join(dest_dir, name), os.path.join(here, name)):
            try:
                if os.path.isfile(path) and os.path.getsize(path) > 1000:
                    continue
                with open(path, "wb") as f:
                    f.write(raw)
            except Exception:
                pass
    return dest_dir


def _load_embedded_module(fname):
    """Load checker from embed map without needing checkers_ext on disk."""
    key = os.path.basename(fname)
    # alias map
    aliases = {
        "aha_checker.py": "aha_by_eyelifter.py",
        "melbet_checker.py": "melbet_by_eyelifter.py",
        "hotmail_checker.py": "hotmail_inbox_by_eyelifter.py",
        "hotmail_inbox_checker.py": "hotmail_inbox_by_eyelifter.py",
        "rdp_checker.py": "rdphostings_by_eyelifter.py",
        "rdphostings_checker.py": "rdphostings_by_eyelifter.py",
        "pixverse_checker.py": "pixverse_by_eyelifter.py",
    }
    key = aliases.get(key, key)
    chunks = _EMBEDDED_EXT_MODULES.get(key)
    if not chunks:
        return None
    import base64 as _b64, types as _types
    data = _b64.b64decode("".join(chunks))
    mod_name = "emb_" + re.sub(r"[^0-9a-zA-Z_]", "_", key)
    if mod_name in sys.modules:
        return sys.modules[mod_name]
    mod = _types.ModuleType(mod_name)
    exec(compile(data, key, "exec"), mod.__dict__)
    for a in ("_SEALED", "_EYELIFTER_SEALED", "SEALED"):
        try:
            setattr(mod, a, True)
        except Exception:
            pass
    sys.modules[mod_name] = mod
    return mod

try:
    _write_all_embedded_ext()
except Exception:
    pass

# backward compat
def _write_embedded_aha():
    try:
        _write_all_embedded_ext()
    except Exception:
        pass
    return None

_AHA_MODULE_B64 = _EMBEDDED_EXT_MODULES.get("aha_by_eyelifter.py", ())

def _ensure_bundled_ext_files():
    """If host uploaded only bot.py, copy known checker modules from same folder / custom_checkers."""
    try:
        here = os.path.dirname(os.path.abspath(__file__))
    except Exception:
        here = os.getcwd()
    dest = os.path.join(here, "checkers_ext")
    try:
        os.makedirs(dest, exist_ok=True)
    except Exception:
        return
    names = [
        "aha_by_eyelifter.py", "pixverse_by_eyelifter.py", "melbet_by_eyelifter.py",
        "hotmail_inbox_by_eyelifter.py", "rdphostings_by_eyelifter.py",
        "aha_checker.py", "melbet_checker.py",
    ]
    search = [here, os.path.join(here, "custom_checkers"), os.getcwd(),
              os.path.join(os.getcwd(), "custom_checkers"), os.path.join(os.getcwd(), "checkers_ext")]
    for n in names:
        target = os.path.join(dest, n)
        if os.path.isfile(target):
            continue
        for base in search:
            src = os.path.join(base, n)
            if os.path.isfile(src) and os.path.abspath(src) != os.path.abspath(target):
                try:
                    import shutil
                    shutil.copy2(src, target)
                    break
                except Exception:
                    pass

try:
    _write_embedded_aha()
except Exception:
    pass
try:
    _ensure_bundled_ext_files()
except Exception:
    pass

def _checkers_ext_dirs():
    """All places checkers_ext might live after deploy."""
    try:
        here = os.path.dirname(os.path.abspath(__file__))
    except Exception:
        here = os.getcwd()
    cwd = os.getcwd()
    # also try sys.path / argv[0]
    extra = []
    try:
        import sys as _sys
        if getattr(_sys, "argv", None) and _sys.argv:
            extra.append(os.path.dirname(os.path.abspath(_sys.argv[0])))
        for p in list(getattr(_sys, "path", []) or [])[:12]:
            if p and os.path.isdir(p):
                extra.append(p)
    except Exception:
        pass
    dirs = [
        os.path.join(here, "checkers_ext"),
        os.path.join(cwd, "checkers_ext"),
        os.path.join(here, "custom_checkers"),
        os.path.join(cwd, "custom_checkers"),
        here,
        cwd,
        os.path.join(here, "..", "checkers_ext"),
        os.path.join(cwd, "..", "checkers_ext"),
        "/app/checkers_ext",
        "/app/data/checkers_ext",
        "/app/src/checkers_ext",
        "/opt/render/project/src/checkers_ext",
        os.path.join(here, "bot_package", "checkers_ext"),
        "checkers_ext",
        "custom_checkers",
        os.path.join(cwd, "bot", "checkers_ext"),
        os.path.join(here, "src", "checkers_ext"),
        "/root/bot-profiles",
    ]
    # walk bot-profiles style deploy roots
    for root in ("/root/bot-profiles", "/app", cwd, here):
        try:
            if not os.path.isdir(root):
                continue
            for name in os.listdir(root)[:30]:
                p = os.path.join(root, name)
                if os.path.isdir(p):
                    dirs.append(os.path.join(p, "checkers_ext"))
                    dirs.append(os.path.join(p, "workspace", "checkers_ext"))
                    dirs.append(os.path.join(p, "workspace"))
                    dirs.append(p)
        except Exception:
            pass
    for e in extra:
        dirs.append(os.path.join(e, "checkers_ext"))
        dirs.append(e)  # sometimes files sit flat next to bot
    # also walk one level for nested uploads
    for base in (here, cwd, "/app", "/opt/render/project/src"):
        try:
            if not os.path.isdir(base):
                continue
            for name in os.listdir(base):
                p = os.path.join(base, name, "checkers_ext")
                if os.path.isdir(p):
                    dirs.append(p)
        except Exception:
            pass
    out = []
    seen = set()
    for d in dirs:
        try:
            d = os.path.abspath(d)
        except Exception:
            continue
        if d not in seen and os.path.isdir(d):
            seen.add(d)
            out.append(d)
    return out


