@bot.callback_query_handler(func=lambda call: call.data == "check_my_proxies")
def handle_check_my_proxies(call):
    uid = call.from_user.id
    try:
        bot.answer_callback_query(call.id, "Checking proxies...")
    except Exception:
        pass
    user_data = get_user(uid) or {}
    proxies = list(user_data.get("proxies") or user_data.get("temp_proxies") or [])
    if not proxies:
        try:
            settings = load_bot_settings()
            proxies = list(settings.get("default_proxies") or [])
        except Exception:
            proxies = []
    if not proxies:
        kb = types.InlineKeyboardMarkup()
        kb.add(ikb("Back To Main Menu", callback_data="back_main", style="danger", emoji="✅"))
        bot.send_message(uid, "%s No proxies stored. Send proxy file / paste / or type <b>skip</b> file or paste, then try again." % E("tg_warn", "⚠️"), parse_mode="HTML", reply_markup=kb)
        return
    bot.send_message(uid, "%s Testing <b>%d</b> proxies..." % (E("tg_search", "🔎"), len(proxies)), parse_mode="HTML")
    try:
        live, dead = test_proxies_fast(proxies)
    except Exception as e:
        live, dead = [], list(proxies)
        try:
            bot.send_message(uid, "%s Proxy test error: %s" % (E("tg_warn", "⚠️"), str(e)[:120]))
        except Exception:
            pass
    user_data = get_user(uid) or {}
    user_data["temp_proxies"] = live
    if live:
        user_data["proxies"] = live
    save_users({str(uid): user_data})
    kb = types.InlineKeyboardMarkup()
    kb.add(ikb("Recheck All Proxies Again", callback_data="check_my_proxies", style="success", emoji="🔄"))
    kb.add(ikb("Back To Main Menu", callback_data="back_main", style="danger", emoji="✅"))
    bot.send_message(
        uid,
        "%s Working: <b>%d</b>\n%s Dead: <b>%d</b>\n%s Live proxies ready for next check." % (
            E("tg_ok", "✅"), len(live), E("tg_no", "❌"), len(dead), E("tg_link", "🔗")
        ),
        parse_mode="HTML",
        reply_markup=kb,
    )


