# ----- FIXED combo extraction -----




def handle_single_check(message, checker_type, checker_id):
    user_id = message.from_user.id
    if message.text and message.text == "/cancel":
        bot.send_message(user_id, e_line("Cancelled", "error", "no", 1)); return
    raw = (message.text or "").strip()
    combo = extract_combo(raw)
    if not combo or ":" not in combo:
        msg = bot.send_message(user_id, f"{EMOJIS['error']} Invalid format! Use <code>identifier:password</code> {EMOJIS['error']}", parse_mode='HTML')
        bot.register_next_step_handler(msg, handle_single_check, checker_type=checker_type, checker_id=checker_id); return
    identifier, password = combo.split(":", 1)
    bot.send_message(user_id, f"{EMOJIS['time']} Checking... {EMOJIS['time']}")
    try:
        # proxies mandatory: try load from proxies.txt next to bot
        proxies = []
        if os.path.exists("proxies.txt"):
            with open("proxies.txt", "r", encoding="utf-8", errors="ignore") as pf:
                for line in pf:
                    line = line.strip()
                    if line and not line.startswith("#"):
                        if not line.startswith("http"):
                            parts = line.split(":")
                            if len(parts) == 4:
                                line = f"http://{parts[2]}:{parts[3]}@{parts[0]}:{parts[1]}"
                            else:
                                line = f"http://{line}"
                        proxies.append(line)
        proxy = safe_choice(proxies, None)
        rotations = 1
        result = None
        last_err = None
        for attempt in range(1):
            try:
                result = run_checker_logic(checker_id, identifier.strip(), password.strip(), proxy)
                st = str(result.get("status", "")).lower()
                if st not in ("error", "timeout", "rate_limit", "retry"):
                    rotations = attempt + 1
                    break
                last_err = result
                BAD = set()
                # rotate proxy
                proxy = safe_choice(proxies, None)
                rotations = attempt + 1
                pass
            except Exception as e:
                last_err = {"status": "error", "message": str(e)[:80]}
                proxy = safe_choice(proxies, None)
                rotations = attempt + 1
                pass
        if result is None:
            result = last_err or {"status": "error", "message": "Unknown"}
        status = str(result.get("status", "error")).lower()
        if status in ["premium", "hit", "valid"]:
            if checker_id == "multichecker" and "results" in result:
                stxt = f"{EMOJIS['success']} HIT (Multi)\n"
                for pname, pres in result["results"].items():
                    pstatus = pres.get("status", "?")
                    if pstatus in ("premium", "hit", "valid"):
                        stxt += f"  ✅ {pname}: {pres.get('message', '')}\n"
                    elif pstatus == "2fa":
                        stxt += f"  🔐 {pname}: 2FA\n"
                    elif pstatus == "free":
                        stxt += f"  📄 {pname}: Free\n"
                    else:
                        stxt += f"  ❌ {pname}: {pstatus}\n"
                bot.send_message(user_id, stxt + f"\nMade By ➜ {CONTACT_ADMIN}", parse_mode="HTML")
            else:
                msg = format_hit_message(identifier.strip(), password.strip(), result, checker_type, rotations)
                bot.send_message(user_id, msg, parse_mode="HTML")
            # admin file only on mass complete — not single
            pass
        elif status in ["free", "expired"]:
            msg = format_hit_message(identifier.strip(), password.strip(), result, checker_type, rotations)
            bot.send_message(user_id, msg, parse_mode="HTML")
        elif status in ["bad", "invalid", "ban"]:
            bot.send_message(user_id, f"{EMOJIS['error']} <b>BAD</b>\nAccount ➜ <code>{identifier}:{password}</code>\nResponse ➜ {result.get('message', 'Invalid')}\n\nMade By ➜ {CONTACT_ADMIN}", parse_mode="HTML")
        elif status == "2fa":
            bot.send_message(user_id, f"{EMOJIS['crown']} <b>2FA REQUIRED</b>\nAccount ➜ <code>{identifier}:{password}</code>\n\nMade By ➜ {CONTACT_ADMIN}", parse_mode="HTML")
        else:
            bot.send_message(user_id, f"{EMOJIS['warn']} <b>ERROR</b>\nAccount ➜ <code>{identifier}:{password}</code>\nResponse ➜ {result.get('message', result.get('error', 'Unknown'))}\n\nMade By ➜ {CONTACT_ADMIN}", parse_mode="HTML")
        update_last_check(user_id)
    except Exception as e:
        bot.send_message(user_id, f"{EMOJIS['error']} Error: {e} {EMOJIS['error']}")

def _resolve_premium_notify_chat():
    """Prefer numeric chat id; fall back to invite link stored in settings."""
    global PREMIUM_NOTIFY_CHAT_ID
    if PREMIUM_NOTIFY_CHAT_ID is not None:
        return PREMIUM_NOTIFY_CHAT_ID
    try:
        st = load_json(SETTINGS_DB, {}) if "SETTINGS_DB" in globals() else {}
    except Exception:
        st = {}
    cid = st.get("premium_notify_chat_id") or os.getenv("PREMIUM_NOTIFY_CHAT_ID")
    if cid:
        try:
            PREMIUM_NOTIFY_CHAT_ID = int(cid)
            return PREMIUM_NOTIFY_CHAT_ID
        except Exception:
            PREMIUM_NOTIFY_CHAT_ID = cid
            return cid
    # last resort: use invite link string (works if bot already in group)
    return PREMIUM_NOTIFY_CHAT


def notify_premium_activated(user_id, username=None, first_name=None, days=30):
    """Post PREMIUM ACTIVATED to channel only. Image from admin media panel key premium_activated."""
    chat = PREMIUM_NOTIFY_CHAT_ID if PREMIUM_NOTIFY_CHAT_ID is not None else -1004345681987
    try:
        users = load_users()
        u = users.get(str(user_id), {}) or {}
        total_hits = int(u.get("total_hits", 0) or 0)
        if not total_hits:
            total_hits = int(u.get("hits", 0) or 0)
        name = first_name or u.get("first_name") or u.get("username") or "—"
        uname = username or u.get("username")
        uname_disp = ("@" + uname) if uname else "—"
        caption = (
            f"{E('tg_ok','✅')} {E('tg_star1','⭐️')} <b>PREMIUM ACTIVATED SUCCESSFULLY</b> {E('tg_gem','💎')} {E('tg_crown','👑')}\n"
            f"━━━━━━━━━━━━━━━━━━━━━\n"
            f"{E('tg_user','👤')} <b>NAME</b> — {str(name).replace('<','').replace('>','')}\n"
            f"{E('tg_tag','🏷')} <b>USERID</b> — <code>{user_id}</code>\n"
            f"{E('tg_chat','💬')} <b>USERNAME</b> — {uname_disp}\n"
            f"{E('tg_star1','⭐️')} <b>TOTAL HITS</b> — {total_hits}\n"
            f"{E('tg_clock','🕓')} <b>DAYS</b> — {days}\n"
            f"━━━━━━━━━━━━━━━━━━━━━\n"
            f"{E('tg_heart','❤️')} THANKS FOR SUPPORT {E('tg_fire','🔥')}"
        )
        # admin panel media first
        img_path = None
        file_id = None
        mtype = "photo"
        try:
            settings = load_bot_settings()
            media = (settings.get("media") or {}).get("premium_activated") or {}
            mtype = media.get("type") or "photo"
            file_id = media.get("file_id")
            p = media.get("path")
            if p and os.path.isfile(p):
                img_path = p
        except Exception:
            pass
        if not img_path:
            base = os.path.dirname(os.path.abspath(__file__))
            for p in (
                os.path.join(base, "premium_activated.jpg"),
                os.path.join(os.getcwd(), "premium_activated.jpg"),
                "premium_activated.jpg",
                "/app/premium_activated.jpg",
            ):
                if os.path.isfile(p):
                    img_path = p
                    break
        sent = False
        if file_id:
            try:
                if mtype == "video":
                    bot.send_video(chat, file_id, caption=caption, parse_mode="HTML"); sent = True
                elif mtype == "animation":
                    bot.send_animation(chat, file_id, caption=caption, parse_mode="HTML"); sent = True
                else:
                    bot.send_photo(chat, file_id, caption=caption, parse_mode="HTML"); sent = True
            except Exception as e1:
                logger.error(f"premium media file_id fail: {e1}")
        if not sent and img_path:
            try:
                with open(img_path, "rb") as ph:
                    bot.send_photo(chat, ph, caption=caption, parse_mode="HTML")
                sent = True
            except Exception as e2:
                logger.error(f"premium media path fail: {e2}")
        if not sent:
            bot.send_message(chat, caption, parse_mode="HTML")
    except Exception as e:
        try:
            bot.send_message(MAIN_ADMIN_ID, f"⚠️ Premium channel post failed:\n<code>{e}</code>\nChat: <code>{chat}</code>", parse_mode="HTML")
        except Exception:
            pass



def handle_redeem(message):
    user_id = message.from_user.id
    if message.text and message.text == "/cancel":
        bot.send_message(user_id, e_line("Cancelled", "error", "no", 1)); return
    raw = (message.text or "").strip()
    if not raw:
        bot.send_message(user_id, f"{EMOJIS['error']} Send a redeem code. {EMOJIS['error']}"); return
    codes = load_redeem_codes()
    # case-insensitive match, trim spaces
    code_key = None
    for k in codes.keys():
        if str(k).strip().upper() == raw.upper():
            code_key = k
            break
    if code_key is None:
        bot.send_message(user_id, f"{EMOJIS['error']} Invalid code! {EMOJIS['error']}"); return
    cdata = codes[code_key]
    if not isinstance(cdata, dict):
        bot.send_message(user_id, f"{EMOJIS['error']} Invalid code data! {EMOJIS['error']}"); return
    if cdata.get("used"):
        bot.send_message(user_id, f"{EMOJIS['error']} This code was already redeemed! {EMOJIS['error']}"); return
    if cdata.get("expires"):
        try:
            if datetime.fromisoformat(cdata["expires"]) < datetime.now():
                bot.send_message(user_id, f"{EMOJIS['error']} Code expired! {EMOJIS['error']}"); return
        except Exception:
            pass
    # one user may redeem only ONE code from the same batch
    batch_id = cdata.get("batch_id")
    if batch_id:
        for ok, od in codes.items():
            if ok == code_key:
                continue
            if not isinstance(od, dict):
                continue
            if od.get("batch_id") == batch_id and od.get("used") and str(od.get("used_by")) == str(user_id):
                bot.send_message(
                    user_id,
                    f"{EMOJIS['error']} You already redeemed a code from this batch!\n"
                    f"One user = one code per batch. {EMOJIS['error']}",
                )
                return
    days = int(cdata.get("days", 30) or 30)
    create_user(user_id, getattr(message.from_user, "username", None))
    users = load_users()
    uid = str(user_id)
    if uid not in users:
        users[uid] = {
            "user_id": user_id,
            "username": getattr(message.from_user, "username", None),
            "is_premium": False,
            "premium_expiry": None,
            "last_check": None,
            "total_checks": 0,
            "total_hits": 0,
        }
    # extend premium if already premium
    now = datetime.now()
    base = now
    try:
        if users[uid].get("is_premium") and users[uid].get("premium_expiry"):
            pe = datetime.fromisoformat(users[uid]["premium_expiry"])
            if pe > now:
                base = pe
    except Exception:
        pass
    users[uid]["is_premium"] = True
    users[uid]["premium_expiry"] = (base + timedelta(days=days)).isoformat()
    users[uid]["username"] = getattr(message.from_user, "username", None) or users[uid].get("username")
    users[uid]["first_name"] = getattr(message.from_user, "first_name", None) or users[uid].get("first_name")
    save_users(users)
    # mark ONLY this code used — other codes in batch stay free
    codes[code_key]["used"] = True
    codes[code_key]["used_by"] = user_id
    codes[code_key]["used_at"] = now.isoformat()
    save_redeem_codes(codes)
    exp_s = (base + timedelta(days=days)).strftime("%Y-%m-%d %H:%M")
    bot.send_message(
        user_id,
        f"{E('tg_ok','✅')} {E('tg_star1','⭐️')} <b>Premium Activated!</b> {E('tg_gem','💎')}\n"
        f"{E('tg_check','✔️')} Duration: <b>{days}</b> days\n"
        f"{E('tg_clock','🕓')} Expires: <code>{exp_s}</code>",
        parse_mode="HTML",
    )
    try:
        notify_premium_activated(
            user_id,
            username=getattr(message.from_user, "username", None),
            first_name=getattr(message.from_user, "first_name", None),
            days=days,
        )
    except Exception as _pe:
        try:
            bot.send_message(MAIN_ADMIN_ID, f"Premium notify exception: {_pe}")
        except Exception:
            pass



