@bot.callback_query_handler(func=lambda call: call.data and call.data.startswith("fj_del_"))
def admin_remove_forcejoin_do(call):
    if not is_admin(call.from_user.id):
        return
    settings = load_bot_settings()
    channels = list(settings.get("force_join_channels") or [])
    key = call.data.replace("fj_del_", "")
    if key == "all":
        settings["force_join_channels"] = []
        save_bot_settings(settings)
        bot.answer_callback_query(call.id, "All cleared")
        bot.send_message(call.message.chat.id, f"{EMOJIS['success']} All force-join channels removed.")
        return
    try:
        idx = int(key)
        removed = channels.pop(idx)
        settings["force_join_channels"] = channels
        save_bot_settings(settings)
        bot.answer_callback_query(call.id, "Removed")
        bot.send_message(
            call.message.chat.id,
            f"{EMOJIS['success']} Removed: <b>{removed.get('title') or removed.get('username') or removed.get('id')}</b>",
            parse_mode="HTML",
        )
    except Exception as e:
        bot.answer_callback_query(call.id, "Error")
        bot.send_message(call.message.chat.id, f"{EMOJIS['error']} {e}")



